// Type returns the decoded discriminant (O(1)), validated against the
// known case set.
func (v ScValView) Type() (ScValType, error) {
	if len(v.d) < 4 {
		return 0, viewErrShortBuffer(0, "need 4 bytes for discriminant")
	}
	val := ScValType(int32(binary.BigEndian.Uint32(v.d[:4])))
	switch val {
	case ScValTypeScvBool, ScValTypeScvVoid, ScValTypeScvError, ScValTypeScvU32, ScValTypeScvI32, ScValTypeScvU64, ScValTypeScvI64, ScValTypeScvTimepoint, ScValTypeScvDuration, ScValTypeScvU128, ScValTypeScvI128, ScValTypeScvU256, ScValTypeScvI256, ScValTypeScvBytes, ScValTypeScvString, ScValTypeScvSymbol, ScValTypeScvVec, ScValTypeScvMap, ScValTypeScvAddress, ScValTypeScvContractInstance, ScValTypeScvLedgerKeyContractInstance, ScValTypeScvLedgerKeyNonce:
		return val, nil
	default:
		return 0, viewErrUnknownDiscriminant(0, int32(val))
	}
}

// ArmB validates that the discriminant selects the B arm and
// returns the arm's sub-view (O(1): only the 4-byte discriminant is read).
func (v ScValView) ArmB() (BoolView, error) {
	if len(v.d) < 4 {
		return BoolView{}, viewErrShortBuffer(0, "need 4 bytes for discriminant")
	}
	disc := int32(binary.BigEndian.Uint32(v.d[:4]))
	switch disc {
	case int32(ScValTypeScvBool):
	default:
		return BoolView{}, viewErrWrongDiscriminant(0, disc, int32(ScValTypeScvBool))
	}
	return BoolView{v.sub(4)}, nil
}

